-- =====================================================================
--  MedClinic · Portal do Paciente — schema + seed
--  Cenário 1 · SQL Injection
--
--  Estrutura e dados extraídos do laboratório em produção (MySQL 8.0.46,
--  database `medclinic`, usuário `appuser`). O seed reproduz fielmente:
--    patients ......... 1000 registros
--    exams ............ 4103 registros
--    users ............ 2 registros (user / admin)
--    secrets .......... 1 registro (a flag do cenário)
--    appointments ..... 0 registros
--    prescriptions .... 0 registros
--
--  Todos os dados são FICTÍCIOS (pessoas, CPFs e convênios gerados para
--  o workshop). Nenhum registro corresponde a uma pessoa real.
--
--  ---------------------------------------------------------------------
--  A FLAG NÃO É HARDCODED NESTE ARQUIVO.
--  A linha abaixo usa o marcador de flag, substituído em tempo de
--  boot por `seed/00-flag.sh` a partir da variável de ambiente C1_FLAG
--  (definida em infra/.env — NUNCA comitada).
-- =====================================================================

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------
--  Tabelas
-- ---------------------------------------------------------------------
DROP TABLE IF EXISTS exams;
DROP TABLE IF EXISTS appointments;
DROP TABLE IF EXISTS prescriptions;
DROP TABLE IF EXISTS secrets;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS patients;

CREATE TABLE patients (
  id           INT          NOT NULL AUTO_INCREMENT,
  name         VARCHAR(100) NOT NULL,
  birthdate    DATE         NULL,
  cpf          VARCHAR(14)  NOT NULL,
  email        VARCHAR(120) NULL,
  phone        VARCHAR(20)  NULL,
  address      VARCHAR(160) NULL,
  insurance    VARCHAR(60)  NULL,
  insurance_id VARCHAR(30)  NULL,
  blood_type   VARCHAR(4)   NULL,
  gender       VARCHAR(12)  NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE users (
  id         INT          NOT NULL AUTO_INCREMENT,
  username   VARCHAR(50)  NOT NULL,
  password   VARCHAR(100) NOT NULL,
  role       VARCHAR(20)  NOT NULL,
  fullname   VARCHAR(100) NOT NULL,
  patient_id INT          NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE exams (
  id         INT          NOT NULL AUTO_INCREMENT,
  patient_id INT          NOT NULL,
  exam_date  DATE         NULL,
  category   VARCHAR(40)  NULL,
  name       VARCHAR(80)  NULL,
  result     VARCHAR(120) NULL,
  reference  VARCHAR(80)  NULL,
  status     VARCHAR(20)  NULL,
  doctor     VARCHAR(80)  NULL,
  PRIMARY KEY (id),
  KEY ix_exams_patient (patient_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE secrets (
  id   INT          NOT NULL AUTO_INCREMENT,
  name VARCHAR(100) NULL,
  flag VARCHAR(100) NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE appointments (
  id         INT          NOT NULL AUTO_INCREMENT,
  patient_id INT          NOT NULL,
  appt_date  DATETIME     NULL,
  doctor     VARCHAR(80)  NULL,
  specialty  VARCHAR(60)  NULL,
  status     VARCHAR(20)  NULL,
  notes      VARCHAR(160) NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE prescriptions (
  id           INT          NOT NULL AUTO_INCREMENT,
  patient_id   INT          NOT NULL,
  rx_date      DATE         NULL,
  medication   VARCHAR(80)  NULL,
  dosage       VARCHAR(60)  NULL,
  instructions VARCHAR(160) NULL,
  doctor       VARCHAR(80)  NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ---------------------------------------------------------------------
--  Seed
-- ---------------------------------------------------------------------
-- Usuários do cenário (login do participante e conta admin)

-- Pacientes fictícios (~1000)

-- Exames fictícios (~4100)

